import{NextResponse}from"next/server";import{prisma}from"@/lib/prisma";import{createExternalExpense}from"@/lib/external";export async function GET(){return NextResponse.json(await prisma.externalExpense.findMany({orderBy:{expenseDate:"desc"}}))}export async function POST(r:Request){try{const b=await r.json(),x=await prisma.$transaction(tx=>createExternalExpense(tx,b));return NextResponse.json(x,{status:201})}catch(e){return NextResponse.json({error:e instanceof Error?e.message:"تعذر الحفظ"},{status:400})}}
